
.sheet {
  width: 100%;
  max-width: 640px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border-strong);
  border-radius: var(--radius);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.42);
  color: var(--c-text);
  font-size: 13px;
  overflow: hidden;
}

.sheet__head {
  padding: 16px 18px 12px;
  background: linear-gradient(160deg, var(--c-surface-raised), var(--c-surface));
  border-bottom: 1px solid var(--c-border);
}

.sheet__title {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--c-primary);
}

.sheet__sub {
  margin-top: 5px;
  font-size: 0.76rem;
  color: var(--c-text-muted);
}

.form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 18px 18px;
}

.row2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.field__label {
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
}

.field__input {
  width: 100%;
  padding: 8px 10px;
  background: var(--c-surface-sunken);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-text);
  font-family: var(--font-ui);
  font-size: 0.8rem;
  line-height: 1.55;
  outline: none;
  transition: border-color 0.16s ease;

  &::placeholder {
    color: var(--c-text-faint);
  }

  &:focus {
    border-color: var(--c-primary-dim);
  }
}

.field__input--area {
  resize: vertical;
  min-height: 56px;
}

.group {
  padding-top: 12px;
  border-top: 1px dashed var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.group__h {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--c-primary);
}

.group__desc {
  font-size: 0.72rem;
  color: var(--c-text-faint);
  line-height: 1.5;
  margin-top: -4px;
}

.group__note {
  font-size: 0.72rem;
  color: var(--c-text-faint);
  line-height: 1.5;
}

.money {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 9px 10px;
  border: 1px solid var(--c-border);
  border-radius: 6px;
  background: var(--c-surface-sunken);
}

.money__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.money__k {
  font-size: 0.74rem;
  color: var(--c-text-muted);
  letter-spacing: 0.08em;
  flex-shrink: 0;
}

.money__ctrl {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.money__unit {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--c-text-faint);
  flex-shrink: 0;
}

.money__num {
  width: 108px;
  text-align: right;
  font-family: var(--font-mono);
}

.money__cycle {
  width: 76px;
}

.money__cny {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--c-text-faint);
  text-align: right;
  min-height: 0;
}

.money__note {
  font-size: 0.76rem;
}

.err {
  font-size: 0.74rem;
  color: var(--c-danger);
}

.submit {
  margin-top: 4px;
  padding: 10px;
  border: 1px solid var(--c-primary-dim);
  border-radius: 6px;
  background: var(--c-primary-dim);
  color: var(--c-text);
  font-family: var(--font-ui);
  font-size: 0.84rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  cursor: pointer;
  transition:
    background 0.18s ease,
    opacity 0.18s ease;

  &:hover:not(:disabled) {
    background: var(--c-primary);
    border-color: var(--c-primary);
    color: #0b0d10;
  }

  &:disabled {
    opacity: 0.45;
    cursor: default;
  }
}

@media (max-width: 520px) {
  .row2 {
    grid-template-columns: 1fr;
  }

  .money__head {
    flex-direction: column;
    align-items: stretch;
  }

  .money__num {
    flex: 1;
    width: auto;
  }
}
